type DemoStage = 'IDLE' | 'SENSE' | 'DETECT' | 'ANALYZE' | 'DECIDE' | 'CONTAIN' | 'ALERT' | 'READY';
type DemoContextType = { demo: boolean; stage: DemoStage; startDemo: () => void; stopDemo: () => void };
const DemoContext = createContext<DemoContextType | null>(null);
const useDemo = () => useContext(DemoContext) as DemoContextType;

const stageFlow = [
  { id: 'SENSE', label: 'Sense', icon: Eye, path: '/analysis' },
  { id: 'DETECT', label: 'Detect', icon: ScanSearch, path: '/analysis' },
  { id: 'ANALYZE', label: 'Analyze', icon: BrainCircuit, path: '/risk' },
  { id: 'DECIDE', label: 'Decide', icon: GitBranch, path: '/decision' },
  { id: 'CONTAIN', label: 'Contain', icon: ShieldCheck, path: '/containment' },
  { id: 'LEARN', label: 'Learn', icon: Database, path: '/architecture' },
] as const;

function DemoProvider({ children }: { children: ReactNode }) {
  const [, setLocation] = useLocation();
  const [demo, setDemo] = useState(false);
  const [stage, setStage] = useState<DemoStage>('IDLE');
  const timer = useRef<number | undefined>(undefined);
  const stages: { stage: DemoStage; path: string }[] = [
    { stage: 'SENSE', path: '/analysis' }, { stage: 'DETECT', path: '/analysis' }, { stage: 'ANALYZE', path: '/risk' },
    { stage: 'DECIDE', path: '/decision' }, { stage: 'CONTAIN', path: '/containment' }, { stage: 'ALERT', path: '/alerts' },
  ];
  const stopDemo = () => {
    if (timer.current) window.clearInterval(timer.current);
    timer.current = undefined;
    setDemo(false); setStage('IDLE');
  };
  const startDemo = () => {
    if (timer.current) window.clearInterval(timer.current);
    setDemo(true); setStage('SENSE'); setLocation('/analysis');
    let index = 0;
    timer.current = window.setInterval(() => {
      index += 1;
      if (index >= stages.length) {
        if (timer.current) window.clearInterval(timer.current);
        timer.current = undefined; setStage('READY'); setLocation('/alerts');
        return;
      }
      setStage(stages[index].stage); setLocation(stages[index].path);
    }, 1450);
  };
  useEffect(() => () => { if (timer.current) window.clearInterval(timer.current); }, []);
  return <DemoContext.Provider value={{ demo, stage, startDemo, stopDemo }}>{children}</DemoContext.Provider>;
}

