function Tag({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'lime' | 'amber' | 'red' | 'teal' }) { const colors = { neutral: 'border-[#304637] bg-[#17261d] text-[#9aac9d]', lime: 'border-lime-300/25 bg-lime-300/10 text-lime-200', amber: 'border-amber-300/25 bg-amber-300/10 text-amber-200', red: 'border-red-300/25 bg-red-300/10 text-red-200', teal: 'border-teal-300/25 bg-teal-300/10 text-teal-200' }; return <span className={`inline-flex items-center rounded-full border px-2.5 py-1 font-mono text-[9px] uppercase tracking-[.12em] ${colors[tone]}`}>{children}</span>; }
function SectionLabel({ children, icon: Icon = Activity }: { children: ReactNode; icon?: typeof Activity }) { return <div className="mb-4 flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.18em] text-[#829687]"><Icon size={13} className="text-lime-300" />{children}</div>; }

