function Analysis() {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState('');
  const [scanning, setScanning] = useState(false);
  const [result, setResult] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  useEffect(() => () => { if (preview) URL.revokeObjectURL(preview); }, [preview]);
  const choose = (next: File | undefined) => { if (!next || !next.type.startsWith('image/')) return; if (preview) URL.revokeObjectURL(preview); setFile(next); setPreview(URL.createObjectURL(next)); setResult(false); };
  const onInput = (e: ChangeEvent<HTMLInputElement>) => choose(e.target.files?.[0]);
  const onDrop = (e: DragEvent<HTMLDivElement>) => { e.preventDefault(); choose(e.dataTransfer.files?.[0]); };
  const run = () => { setScanning(true); setResult(false); window.setTimeout(() => { setScanning(false); setResult(true); }, 3100); };
  return <div className="animate-in"><PageHeader eyebrow="SENSE / DETECT" title="AI crop analysis" detail="Inspect a crop image for early symptoms. The vision pass is simulated for this prototype demonstration." action={<Tag tone="teal">Prototype scan / local</Tag>} /><div className="grid gap-5 xl:grid-cols-[1.05fr_.95fr]"><Panel className="p-6"><SectionLabel icon={UploadCloud}>Input surface</SectionLabel><div onDragOver={e => e.preventDefault()} onDrop={onDrop} onClick={() => inputRef.current?.click()} className={`relative flex min-h-[320px] cursor-pointer flex-col items-center justify-center overflow-hidden rounded-2xl border border-dashed ${preview ? 'border-lime-300/40 bg-[#0f2117]' : 'border-[#48614d] bg-[#112219]'} transition hover:border-lime-300/70`} data-testid="dropzone-crop-image">{preview ? <><img src={preview} alt="Uploaded crop sample" className="absolute inset-0 size-full object-cover opacity-60" /><div className="absolute inset-0 bg-[#08150d]/40" /><div className="scan-line absolute left-0 right-0 top-0 h-1 bg-lime-300 shadow-[0_0_18px_hsl(77_55%_57%/.8)]" /><div className="relative z-10 grid place-items-center rounded-full border border-lime-300/50 bg-[#122a1b]/80 p-4 text-lime-300"><ImageIcon size={26} /></div><p className="relative z-10 mt-4 text-sm font-semibold">{file?.name ?? 'Crop image ready'}</p><p className="relative z-10 mt-1 text-[11px] text-[#b2c2ad]">Click or drop a different image to replace</p></> : <><div className="mb-5 grid size-14 place-items-center rounded-2xl border border-[#3c5942] bg-[#193021] text-lime-300"><UploadCloud size={25} /></div><p className="text-sm font-semibold">Drop a crop image here</p><p className="mt-2 text-center text-xs text-[#829687]">JPG, PNG or WEBP · up to 10 MB</p><span className="mt-5 rounded-lg border border-[#38523e] px-3 py-2 text-[10px] font-bold uppercase tracking-[.12em] text-[#c1cfbf]">Browse files</span></>}<input ref={inputRef} onChange={onInput} type="file" accept="image/*" className="hidden" data-testid="input-crop-image" /></div><div className="mt-4 flex items-center justify-between"><p className="flex items-center gap-2 text-[10px] text-[#829687]"><LockKeyhole size={13} className="text-teal-300" />Image stays in this browser session</p>{file && <button onClick={e => { e.stopPropagation(); setFile(null); setPreview(''); }} className="text-[10px] font-bold text-[#dd928b] hover:text-red-200" data-testid="button-clear-image">Clear image</button>}</div></Panel>
      <Panel className="p-6"><SectionLabel icon={ScanLine}>Analysis console</SectionLabel><div className="flex min-h-[320px] flex-col justify-between"><div><div className="mb-6 flex items-center justify-between"><div><p className="font-display text-2xl font-semibold">Tomato / Block C</p><p className="mt-1 text-xs text-[#829687]">Expected pass: leaf morphology + lesion pattern</p></div><Tag tone={scanning ? 'amber' : result ? 'lime' : 'neutral'}>{scanning ? 'Processing' : result ? 'Complete' : 'Awaiting input'}</Tag></div>{scanning ? <div className="space-y-5">{['Normalizing image surface', 'Comparing symptom signatures', 'Scoring confidence + severity'].map((text, i) => <motion.div key={text} initial={{ opacity: 0, x: -12 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * .6 }} className="flex items-center gap-3"><span className="grid size-7 place-items-center rounded-lg border border-amber-300/30 bg-amber-300/10 text-amber-200"><RefreshCw size={13} className="animate-spin" /></span><div className="flex-1"><div className="flex justify-between text-[11px]"><span>{text}</span><span className="font-mono text-[#829687]">{i === 0 ? 'complete' : i === 1 ? 'running' : 'queued'}</span></div><div className="mt-2 h-1 rounded-full bg-[#294435]"><motion.div initial={{ width: '4%' }} animate={{ width: i === 0 ? '100%' : i === 1 ? '68%' : '22%' }} transition={{ duration: 1.2 }} className="h-full rounded-full bg-amber-300" /></div></div></motion.div>)}</div> : result ? <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} className="rounded-2xl border border-red-300/25 bg-red-300/10 p-5"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-red-200">Signal detected</p><p className="mt-2 font-display text-2xl font-bold text-[#f3e7df]">Tomato Leaf Blight</p></div><ShieldAlert className="text-red-300" size={23} /></div><div className="mt-5 grid grid-cols-2 gap-3"><div><p className="text-[10px] uppercase text-[#c09b94]">Confidence</p><p className="mt-1 font-display text-xl font-bold">92.7%</p></div><div><p className="text-[10px] uppercase text-[#c09b94]">Severity</p><p className="mt-1 font-display text-xl font-bold text-red-200">HIGH</p></div><div><p className="text-[10px] uppercase text-[#c09b94]">Affected area</p><p className="mt-1 font-display text-xl font-bold">14.8%</p></div><div><p className="text-[10px] uppercase text-[#c09b94]">Target</p><p className="mt-1 text-xs font-semibold">Block C · Rows 12–18</p></div></div></motion.div> : <div className="flex h-48 flex-col items-center justify-center rounded-2xl border border-[#294435] bg-[#12241a] text-center"><CircleDot size={28} className="mb-3 text-[#55705b]" /><p className="text-sm font-semibold">Ready for a field sample</p><p className="mt-1 max-w-xs text-xs leading-5 text-[#829687]">Use the demo path to simulate a confirmed high-risk detection without an upload.</p></div>}</div><div className="mt-6 flex items-center justify-between border-t border-[#294435] pt-5"><p className="max-w-[220px] text-[10px] leading-4 text-[#718477]">Prototype / demo simulation. Not a scientific diagnosis.</p><button disabled={scanning} onClick={run} className="flex items-center gap-2 rounded-xl bg-lime-300 px-4 py-3 text-xs font-bold text-[#132118] transition hover:bg-lime-200 disabled:cursor-wait disabled:opacity-60" data-testid="button-demo-analysis">{scanning ? <RefreshCw size={14} className="animate-spin" /> : <Zap size={14} />} {scanning ? 'Running scan…' : 'Run demo analysis'}</button></div></div></Panel></div></div>;
}

const projection = [{ day: 'Now', risk: 82 }, { day: '+6h', risk: 84 }, { day: '+12h', risk: 87 }, { day: '+18h', risk: 89 }, { day: '+24h', risk: 91 }];
function Risk() {
  const [selected, setSelected] = useState('C');
  return <div className="animate-in"><PageHeader eyebrow="ANALYZE / CONTEXT" title="Risk intelligence" detail="A clear view of what is happening now, where it could move, and how quickly the response window is closing." action={<Tag tone="red"><span className="mr-1.5 size-1.5 rounded-full bg-red-300" />High risk / 82</Tag>} /><div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><Panel className="p-6"><SectionLabel icon={Gauge}>Current risk index</SectionLabel><div className="flex items-center gap-7"><div className="relative grid size-40 place-items-center rounded-full" style={{ background: 'conic-gradient(#ed7169 0 82%, #294435 82% 100%)' }}><div className="grid size-[124px] place-items-center rounded-full bg-[#102117] text-center"><span className="font-display text-5xl font-bold">82</span><span className="font-mono text-[9px] uppercase tracking-[.16em] text-[#829687]">/ 100</span></div></div><div><Tag tone="red">Escalate</Tag><p className="mt-3 text-sm font-semibold">Response window: 6–12 hours</p><p className="mt-2 text-xs leading-5 text-[#829687]">Weather and proximity signals are aligned with a localized spread pattern.</p></div></div><div className="mt-8 space-y-4 border-t border-[#294435] pt-5">{[['Symptom confidence', '92.7%', 'lime', 93], ['Affected area', '14.8%', 'amber', 42], ['Spread velocity', 'High', 'red', 78]].map(([name, val, tone, width]) => <div key={name}><div className="mb-2 flex justify-between text-xs"><span className="text-[#9aac9d]">{name}</span><span className={`font-mono ${tone === 'red' ? 'text-red-200' : tone === 'amber' ? 'text-amber-200' : 'text-lime-200'}`}>{val}</span></div><div className="h-1.5 rounded-full bg-[#294435]"><motion.div initial={{ width: 0 }} animate={{ width: `${width}%` }} className={`h-full rounded-full ${tone === 'red' ? 'bg-red-300' : tone === 'amber' ? 'bg-amber-300' : 'bg-lime-300'}`} /></div></div>)}</div></Panel><Panel className="p-6"><div className="mb-5 flex items-start justify-between"><div><SectionLabel icon={Activity}>Simulated projection</SectionLabel><h2 className="font-display text-xl font-semibold">Risk trajectory</h2><p className="mt-1 text-xs text-[#829687]">Projected risk score if no action is taken</p></div><Tag tone="amber">+9 pts / 24h</Tag></div><div className="h-[245px] w-full"><ResponsiveContainer width="100%" height="100%"><AreaChart data={projection} margin={{ top: 15, right: 5, left: -22, bottom: 0 }}><defs><linearGradient id="riskFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#ed7169" stopOpacity=".35" /><stop offset="100%" stopColor="#ed7169" stopOpacity="0" /></linearGradient></defs><CartesianGrid stroke="#294435" strokeDasharray="3 4" vertical={false} /><XAxis dataKey="day" tick={{ fill: '#829687', fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis domain={[70, 100]} tick={{ fill: '#829687', fontSize: 10 }} axisLine={false} tickLine={false} /><ChartTooltip contentStyle={{ background: '#15291e', border: '1px solid #38523e', borderRadius: 10, color: '#eef0df', fontSize: 11 }} /><Area type="monotone" dataKey="risk" stroke="#ed7169" strokeWidth={3} fill="url(#riskFill)" dot={{ fill: '#ed7169', strokeWidth: 0, r: 4 }} /></AreaChart></ResponsiveContainer></div><div className="grid grid-cols-3 gap-2 border-t border-[#294435] pt-4 text-center"><div><p className="font-display text-lg font-bold text-amber-200">82%</p><p className="font-mono text-[9px] text-[#718477]">NOW</p></div><div><p className="font-display text-lg font-bold text-amber-200">87%</p><p className="font-mono text-[9px] text-[#718477]">+12 HOURS</p></div><div><p className="font-display text-lg font-bold text-red-200">91%</p><p className="font-mono text-[9px] text-[#718477]">+24 HOURS</p></div></div></Panel></div><Panel className="mt-5 p-6"><div className="mb-5 flex items-center justify-between"><div><SectionLabel icon={MapPinned}>Spatial risk field</SectionLabel><h2 className="font-display text-xl font-semibold">Affected zone heatmap</h2></div><div className="flex gap-2"><Tag tone="teal">Healthy</Tag><Tag tone="amber">Watch</Tag><Tag tone="red">High risk</Tag></div></div><div className="relative overflow-hidden rounded-2xl border border-[#294435] bg-[#102117] p-3"><div className="grid grid-cols-6 gap-1.5 md:grid-cols-12">{Array.from({ length: 72 }, (_, i) => { const isHot = i >= 42 && i <= 58 && i % 6 !== 0; const isWatch = (i > 26 && i < 43) || (i > 58 && i < 66); return <button key={i} onClick={() => setSelected(isHot ? 'C' : isWatch ? 'B' : 'A')} className={`relative h-8 rounded-sm transition hover:scale-105 ${isHot ? 'bg-red-300/70' : isWatch ? 'bg-amber-300/45' : 'bg-teal-300/20'}`} aria-label={`Field cell ${i + 1}`} data-testid={`button-heatmap-cell-${i + 1}`}>{isHot && i === 49 && <span className="pulse-ring absolute inset-1 rounded-sm border-2 border-red-200/80" />}</button>; })}</div><div className="mt-3 flex justify-between font-mono text-[9px] uppercase tracking-[.15em] text-[#718477]"><span>North / access road</span><span>South / irrigation line</span></div></div><div className="mt-4 flex items-center justify-between rounded-xl border border-red-300/15 bg-red-300/[.06] px-4 py-3"><div className="flex items-center gap-3"><Target size={17} className="text-red-300" /><span className="text-xs"><strong>Block {selected}</strong> selected · {selected === 'C' ? 'Rows 12–18 require localized containment' : 'monitoring only — no action recommended'}</span></div><Link href={selected === 'C' ? '/decision' : '/analysis'} className="flex items-center gap-1 text-[10px] font-bold uppercase tracking-[.1em] text-lime-300" data-testid="link-risk-next-step">Continue <ArrowRight size={13} /></Link></div></Panel></div>;
}

function Decision() {
  const [running, setRunning] = useState(false);
  const [step, setStep] = useState(4);
  const run = () => { setRunning(true); setStep(0); [0, 1, 2, 3, 4].forEach((n, i) => window.setTimeout(() => { setStep(n); if (n === 4) setRunning(false); }, i * 650)); };
  const factors = [{ label: 'Confidence', value: '92.7%', icon: BrainCircuit }, { label: 'Severity', value: 'HIGH', icon: AlertTriangle }, { label: 'Footprint', value: '14.8%', icon: Layers3 }, { label: 'Proximity', value: 'Adjacent rows', icon: MapPinned }];
  return <div className="animate-in"><PageHeader eyebrow="DECIDE / ORCHESTRATE" title="Autonomous decision agent" detail="A concise, auditable recommendation assembled from the active field signals. No hidden reasoning — only the factors a farmer can act on." action={<button onClick={run} className="flex items-center gap-2 rounded-xl border border-[#44614a] bg-[#172c1f] px-4 py-2.5 text-xs font-bold text-[#dbe5d2] transition hover:bg-[#22432e]" data-testid="button-rerun-decision"><RotateCcw size={14} className={running ? 'animate-spin' : ''} />{running ? 'Re-evaluating' : 'Re-run assessment'}</button>} /><div className="grid gap-5 xl:grid-cols-[1fr_.85fr]"><Panel className="p-6"><SectionLabel icon={GitBranch}>Decision pipeline</SectionLabel><div className="space-y-2">{['Signal received', 'Risk threshold crossed', 'Affected zone isolated', 'Healthy zones excluded', 'Action recommendation'].map((label, i) => <motion.div key={label} initial={{ opacity: 0, x: -8 }} animate={{ opacity: i <= step ? 1 : .38, x: 0 }} className={`flex items-center gap-4 rounded-xl border p-4 transition ${i === step ? 'border-lime-300/40 bg-lime-300/10' : 'border-[#294435] bg-[#12241a]'}`}><span className={`grid size-8 place-items-center rounded-lg font-mono text-xs ${i < step ? 'bg-lime-300 text-[#132118]' : i === step ? 'bg-[#c4db77] text-[#132118]' : 'bg-[#20372a] text-[#829687]'}`}>{i < step ? <Check size={15} /> : `0${i + 1}`}</span><div className="flex-1"><p className="text-xs font-semibold">{label}</p><p className="mt-1 text-[10px] text-[#829687]">{['Vision model confirms Tomato Leaf Blight', 'Score 82 / 100 requires field response', 'Block C · Rows 12–18', 'Blocks A + B remain in monitoring', 'Targeted treatment + isolation'][i]}</p></div>{i === step && <span className="live-dot size-2 rounded-full bg-lime-300" />}</motion.div>)}</div></Panel><Panel className="p-6"><SectionLabel icon={FileCheck2}>Recommended action</SectionLabel><div className="rounded-2xl border border-lime-300/25 bg-lime-300/[.07] p-5"><div className="flex items-start justify-between"><div><Tag tone="lime">Ready to execute</Tag><h2 className="mt-4 font-display text-2xl font-bold leading-tight">Targeted treatment<br />+ isolation</h2></div><ShieldCheck size={25} className="text-lime-300" /></div><p className="mt-4 text-xs leading-5 text-[#a5b5a5]">Apply a localized response to the affected zone. Keep healthy zones excluded to prevent unnecessary intervention.</p><div className="mt-5 space-y-2 border-t border-lime-300/15 pt-4 text-xs"><div className="flex justify-between"><span className="text-[#829687]">Target</span><strong>Block C / Rows 12–18</strong></div><div className="flex justify-between"><span className="text-[#829687]">Coverage</span><strong>14.8% affected area</strong></div><div className="flex justify-between"><span className="text-[#829687]">Healthy zones</span><strong className="text-teal-300">Excluded</strong></div></div></div><Link href="/containment" className="mt-4 flex w-full items-center justify-center gap-2 rounded-xl bg-lime-300 py-3 text-xs font-bold text-[#132118] transition hover:bg-lime-200" data-testid="link-decision-containment">Open containment plan <ArrowRight size={14} /></Link></Panel></div><Panel className="mt-5 p-6"><SectionLabel icon={SlidersHorizontal}>Decision factors</SectionLabel><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{factors.map(({ label, value, icon: Icon }) => <div key={label} className="flex items-center gap-3 rounded-xl border border-[#294435] bg-[#12241a] p-4"><Icon size={17} className="text-amber-300" /><div><p className="text-[10px] text-[#718477]">{label}</p><p className="mt-1 text-sm font-semibold">{value}</p></div></div>)}</div></Panel></div>;
}

function Containment() {
  const [generated, setGenerated] = useState(false);
  const [selected, setSelected] = useState('C');
  const blocks = [{ id: 'A', area: '8.2 ac', status: 'Healthy', tone: 'teal' }, { id: 'B', area: '7.1 ac', status: 'Monitoring', tone: 'amber' }, { id: 'C', area: '9.3 ac', status: 'Affected · 14.8%', tone: 'red' }];
  return <div className="animate-in"><PageHeader eyebrow="CONTAIN / LOCALIZE" title="Containment map" detail="Translate the recommendation into a precise field boundary. Review the target block before generating the response plan." action={<Tag tone={generated ? 'lime' : 'amber'}>{generated ? 'Plan generated' : 'Action required'}</Tag>} /><div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><Panel className="p-6"><div className="mb-5 flex items-center justify-between"><SectionLabel icon={Target}>Field boundary</SectionLabel><span className="font-mono text-[9px] uppercase tracking-[.15em] text-[#718477]">click a block to inspect</span></div><div className="relative overflow-hidden rounded-2xl border border-[#35503e] bg-[#0f2117] p-4"><div className="absolute inset-0 opacity-40" style={{ backgroundImage: 'linear-gradient(90deg, #294435 1px, transparent 1px), linear-gradient(#294435 1px, transparent 1px)', backgroundSize: '25px 25px' }} /><div className="relative grid min-h-[365px] grid-cols-3 gap-3 md:gap-5"><button onClick={() => setSelected('A')} className={`relative mt-12 rounded-xl border-2 ${selected === 'A' ? 'border-teal-300/80' : 'border-teal-300/25'} bg-teal-300/[.13] p-3 text-left transition hover:-translate-y-1`} data-testid="button-block-a"><span className="absolute -top-3 left-3 rounded-md bg-[#17372a] px-2 py-1 font-mono text-[9px] text-teal-200">BLOCK A</span><span className="absolute bottom-4 left-3 right-3 h-px bg-teal-300/20" /><span className="absolute bottom-6 left-3 font-mono text-[9px] text-teal-200/80">HEALTHY</span></button><button onClick={() => setSelected('B')} className={`relative mt-5 rounded-xl border-2 ${selected === 'B' ? 'border-amber-300/80' : 'border-amber-300/30'} bg-amber-300/[.12] p-3 text-left transition hover:-translate-y-1`} data-testid="button-block-b"><span className="absolute -top-3 left-3 rounded-md bg-[#49361c] px-2 py-1 font-mono text-[9px] text-amber-200">BLOCK B</span><span className="absolute bottom-4 left-3 right-3 h-px bg-amber-300/20" /><span className="absolute bottom-6 left-3 font-mono text-[9px] text-amber-200/80">MONITOR</span></button><button onClick={() => setSelected('C')} className={`pulse-ring relative mt-16 rounded-xl border-2 ${selected === 'C' ? 'border-red-200' : 'border-red-300/70'} bg-red-300/[.20] p-3 text-left transition hover:-translate-y-1`} data-testid="button-block-c"><span className="absolute -top-3 left-3 rounded-md bg-[#552c27] px-2 py-1 font-mono text-[9px] text-red-100">BLOCK C</span><div className="absolute inset-4 rounded-lg border border-dashed border-red-200/70" /><span className="absolute bottom-4 left-3 font-mono text-[9px] text-red-100">ROWS 12–18</span></button></div><div className="relative mt-3 flex items-center justify-between border-t border-[#294435] pt-3 font-mono text-[9px] uppercase tracking-[.14em] text-[#718477]"><span>North gate</span><span className="flex items-center gap-2 text-red-200"><span className="size-1.5 rounded-full bg-red-300" />containment boundary</span><span>Irrigation line</span></div></div></Panel><Panel className="p-6"><SectionLabel icon={ShieldCheck}>Localized action plan</SectionLabel><div className="mb-5 flex items-center justify-between"><div><p className="font-display text-2xl font-bold">Block {selected}</p><p className="mt-1 text-xs text-[#829687]">{blocks.find(b => b.id === selected)?.area} · {blocks.find(b => b.id === selected)?.status}</p></div><MapPinned className={selected === 'C' ? 'text-red-300' : 'text-teal-300'} size={24} /></div>{selected === 'C' ? <div className="space-y-3">{[['01', 'Isolate rows 12–18', 'Create a no-crossing boundary'], ['02', 'Target localized treatment', 'Avoid Blocks A and B'], ['03', 'Notify field operator', 'Send high-risk response alert']].map(([n, title, sub]) => <div key={n} className="flex gap-3 rounded-xl border border-[#294435] bg-[#12241a] p-3"><span className="font-mono text-[10px] text-red-200">{n}</span><div><p className="text-xs font-semibold">{title}</p><p className="mt-1 text-[10px] text-[#829687]">{sub}</p></div></div>)}</div> : <div className="rounded-xl border border-teal-300/20 bg-teal-300/[.06] p-4 text-xs leading-5 text-[#a9bcad]">No containment action recommended. Keep this block in the monitoring set while Block C is isolated.</div>}<button onClick={() => setGenerated(true)} className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-lime-300 py-3 text-xs font-bold text-[#132118] transition hover:bg-lime-200" data-testid="button-generate-containment"><Zap size={14} />{generated ? 'Containment plan active' : 'Generate containment plan'}</button>{generated && <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} className="mt-3 flex items-center gap-2 rounded-xl border border-lime-300/25 bg-lime-300/10 p-3 text-xs text-lime-100"><CheckCircle2 size={15} />Plan staged · operator alert queued</motion.div>}</Panel></div></div>;
}

function Alerts() {
  const [resolved, setResolved] = useState<string[]>([]);
  const dismiss = (id: string) => setResolved(value => [...value, id]);
  const alerts = [{ id: 'high', title: 'High-risk outbreak signal', detail: 'Tomato Leaf Blight · Block C · Rows 12–18', time: '4 min ago', tone: 'red', icon: ShieldAlert }, { id: 'monitor', title: 'Monitoring threshold crossed', detail: 'Block B has moved from 39 to 47 / 100', time: '18 min ago', tone: 'amber', icon: Activity }];
  return <div className="animate-in"><PageHeader eyebrow="ALERT / RESPOND" title="Alerts & response" detail="The farmer-facing handoff: what needs attention, what is already staged, and what can wait." action={<Tag tone="red">1 unresolved alert</Tag>} /><div className="mb-5 grid gap-4 md:grid-cols-3"><Panel className="p-5"><div className="flex items-center justify-between"><span className="text-xs text-[#829687]">Unresolved</span><Bell size={16} className="text-red-300" /></div><p className="mt-3 font-display text-3xl font-bold">{alerts.filter(a => !resolved.includes(a.id)).length}</p><p className="mt-1 text-[10px] text-[#718477]">requires operator review</p></Panel><Panel className="p-5"><div className="flex items-center justify-between"><span className="text-xs text-[#829687]">Response status</span><Radio size={16} className="text-lime-300" /></div><p className="mt-3 font-display text-3xl font-bold text-lime-200">Staged</p><p className="mt-1 text-[10px] text-[#718477]">localized plan ready</p></Panel><Panel className="p-5"><div className="flex items-center justify-between"><span className="text-xs text-[#829687]">Last sync</span><Timer size={16} className="text-teal-300" /></div><p className="mt-3 font-display text-3xl font-bold">14:32</p><p className="mt-1 text-[10px] text-[#718477]">all nodes reporting</p></Panel></div><div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><Panel className="p-6"><SectionLabel icon={Bell}>Active queue</SectionLabel><div className="space-y-3">{alerts.map(alert => resolved.includes(alert.id) ? null : <motion.div layout key={alert.id} className={`rounded-2xl border p-5 ${alert.tone === 'red' ? 'border-red-300/25 bg-red-300/[.07]' : 'border-amber-300/25 bg-amber-300/[.06]'}`} data-testid={`card-alert-${alert.id}`}><div className="flex items-start gap-4"><span className={`grid size-10 place-items-center rounded-xl ${alert.tone === 'red' ? 'bg-red-300/15 text-red-300' : 'bg-amber-300/15 text-amber-300'}`}><alert.icon size={19} /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-sm font-bold">{alert.title}</p><span className="font-mono text-[9px] text-[#829687]">{alert.time}</span></div><p className="mt-2 text-xs text-[#a7b5a6]">{alert.detail}</p><div className="mt-4 flex flex-wrap gap-2"><Link href={alert.id === 'high' ? '/containment' : '/risk'} className={`flex items-center gap-1.5 rounded-lg px-3 py-2 text-[10px] font-bold ${alert.tone === 'red' ? 'bg-red-300 text-[#2d1714]' : 'bg-amber-300 text-[#2d2113]'}`} data-testid={`link-view-alert-${alert.id}`}>View affected zone <ArrowUpRight size={13} /></Link><button onClick={() => dismiss(alert.id)} className="rounded-lg border border-[#49614c] px-3 py-2 text-[10px] font-bold text-[#b1c0b1] hover:bg-[#263c2c]" data-testid={`button-dismiss-alert-${alert.id}`}>Mark reviewed</button></div></div></div></motion.div>)}</div>{resolved.length === alerts.length && <div className="rounded-2xl border border-lime-300/20 bg-lime-300/[.06] p-8 text-center"><CheckCircle2 className="mx-auto text-lime-300" size={27} /><p className="mt-3 font-display text-lg font-semibold">Queue clear</p><p className="mt-1 text-xs text-[#829687]">All simulated alerts have been reviewed.</p><button onClick={() => setResolved([])} className="mt-4 text-xs font-bold text-lime-300" data-testid="button-reset-alerts">Restore demo alerts</button></div>}</Panel><Panel className="p-6"><SectionLabel icon={Send}>Farmer handoff</SectionLabel><div className="rounded-2xl border border-[#38523e] bg-[#12241a] p-5"><div className="flex items-center justify-between"><div className="flex items-center gap-3"><span className="grid size-9 place-items-center rounded-full bg-[#294b36] text-lime-200">JR</span><div><p className="text-xs font-bold">Juno Ridge Farm</p><p className="font-mono text-[9px] text-[#718477]">operator channel / simulation</p></div></div><Tag tone="teal">Ready</Tag></div><div className="my-5 border-y border-[#294435] py-4 text-sm leading-6 text-[#c5d0c2]">“High risk detected in Block C. Recommended action: targeted treatment and isolation of Rows 12–18. Healthy zones excluded.”</div><button onClick={() => dismiss('high')} className="flex w-full items-center justify-center gap-2 rounded-xl border border-lime-300/30 bg-lime-300/10 py-3 text-xs font-bold text-lime-200 transition hover:bg-lime-300/20" data-testid="button-send-farmer-alert"><Send size={14} />Simulate farmer alert sent</button></div><div className="mt-4 flex items-center gap-2 text-[10px] text-[#718477]"><LockKeyhole size={13} className="text-teal-300" />Prototype message only · no external delivery</div></Panel></div></div>;
}

function Architecture() {
  const systems = [{ name: 'Field sensors', icon: Radio, detail: 'moisture · canopy · weather' }, { name: 'Vision layer', icon: ScanSearch, detail: 'leaf images · symptom signals' }, { name: 'Risk engine', icon: BrainCircuit, detail: 'confidence · spread projection' }, { name: 'Action layer', icon: ShieldCheck, detail: 'containment · farmer alert' }];
  return <div className="animate-in"><PageHeader eyebrow="SYSTEM / LEARN" title="System architecture" detail="A transparent view of how CropGuard moves from field signal to operator action — and how every response creates a better next pass." action={<Tag tone="teal">4 active layers</Tag>} /><Panel className="overflow-hidden p-6 md:p-8"><div className="mb-8 flex items-center justify-between"><div><SectionLabel icon={Network}>Signal architecture</SectionLabel><h2 className="font-display text-2xl font-semibold">The field intelligence loop</h2></div><span className="font-mono text-[9px] uppercase tracking-[.15em] text-[#718477]">prototype topology / v0.8</span></div><div className="grid gap-3 md:grid-cols-4">{systems.map(({ name, icon: Icon, detail }, i) => <div key={name} className="relative"><div className="rounded-2xl border border-[#38523e] bg-[#12241a] p-5 transition hover:-translate-y-1 hover:border-lime-300/40"><div className="mb-5 flex items-center justify-between"><span className="font-mono text-[10px] text-lime-300">0{i + 1}</span><Icon size={21} className="text-[#a9c778]" /></div><p className="font-display text-lg font-semibold">{name}</p><p className="mt-2 text-[10px] leading-4 text-[#829687]">{detail}</p><div className="mt-5 flex items-center gap-2 text-[9px] font-mono uppercase tracking-[.12em] text-teal-300"><span className="live-dot size-1.5 rounded-full bg-teal-300" />online</div></div>{i < 3 && <ArrowRight size={16} className="absolute -right-2.5 top-1/2 z-10 hidden -translate-y-1/2 text-lime-300 md:block" />}</div>)}</div><div className="mt-6 rounded-xl border border-dashed border-[#38523e] bg-[#102117] px-4 py-3 text-center font-mono text-[10px] text-[#829687]"><span className="text-lime-300">Continuous feedback</span> · operator outcomes return to the learning layer for the next simulated cycle</div></Panel><div className="mt-5 grid gap-5 md:grid-cols-[.8fr_1.2fr]"><Panel className="p-6"><SectionLabel icon={Database}>Data posture</SectionLabel><div className="space-y-4">{[['Images processed', '1,284'], ['Decision traces', '38'], ['Zones modeled', '03'], ['Model state', 'Prototype']].map(([label, value]) => <div key={label} className="flex items-center justify-between border-b border-[#294435] pb-3 last:border-0 last:pb-0"><span className="text-xs text-[#829687]">{label}</span><span className="font-mono text-xs text-[#d9e3d2]">{value}</span></div>)}</div></Panel><Panel className="p-6"><SectionLabel icon={RefreshCw}>Continuous learning</SectionLabel><div className="flex flex-col gap-5 sm:flex-row sm:items-center"><div className="relative grid size-28 shrink-0 place-items-center rounded-full border border-teal-300/25 bg-teal-300/[.07]"><RefreshCw size={32} className="text-teal-300" /><span className="absolute -right-1 top-3 grid size-5 place-items-center rounded-full bg-lime-300 text-[#132118]"><Check size={12} /></span></div><div><h2 className="font-display text-xl font-semibold">Every response becomes context</h2><p className="mt-2 max-w-xl text-xs leading-5 text-[#829687]">In this prototype, simulated operator feedback updates the field record so the next scan can compare signal, decision, and outcome in one traceable loop.</p><div className="mt-4 flex flex-wrap gap-2"><Tag tone="teal">Traceable</Tag><Tag tone="lime">Human-readable</Tag><Tag>Prototype only</Tag></div></div></div></Panel></div></div>;
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function Router() { return <RoutedErrorBoundary><Switch><Route path="/" component={Dashboard} /><Route path="/analysis" component={Analysis} /><Route path="/risk" component={Risk} /><Route path="/decision" component={Decision} /><Route path="/containment" component={Containment} /><Route path="/alerts" component={Alerts} /><Route path="/architecture" component={Architecture} /><Route component={NotFound} /></Switch></RoutedErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><DemoProvider><Shell><Router /></Shell></DemoProvider></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;